package com.fooddelivery.auth; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.util.*; @Service public class JwtService{private final javax.crypto.SecretKey key; JwtService(@Value("${app.jwt.secret}")String s){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));} String token(User u){return Jwts.builder().subject(u.getEmail()).claim("role",u.getRole().name()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+86400000)).signWith(key).compact();}}